```java
private boolean isFormatAsBlock(Document.OutputSettings out) {
    if (style().getDisplay() == Display.INLINE) {
        return false;
    }
    return tag.formatAsBlock() || (parent() != null && parent().tag().formatAsBlock()) || out.outline();
